JS=json.loads("\"\\nconst scenes=JSON.parse(document.querySelector('#scene-data').textContent),panels=[...document.querySelectorAll('.scene')],nav=[...document.querySelectorAll('[data-scene]')];let index=0,elapsed=0,started=null,notesOpen=false;const q=s=>document.querySelector(s);\\nfunction refreshScript(){q('#script-title').textContent=scenes[index].nav;q('#script-content').replaceChildren(...scenes[index].speech.map(t=>{const p=document.createElement('p');p.textContent=t;return p;}));q('#script-cue').textContent='Screen cue · '+scenes[index].cue}\\nfunction show(i){index=Math.max(0,Math.min(i,scenes.length-1));panels.forEach((p,j)=>p.hidden=j!==index);nav.forEach((b,j)=>j===index?b.setAttribute('aria-current','step'):b.removeAttribute('aria-current'));q('#prev').disabled=index===0;q('#next').disabled=index===scenes.length-1;q('#side-number').textContent=String(index+1).padStart(2,'0');q('#side-title').textContent=scenes[index].side[0];q('#side-text').textContent=scenes[index].side[1];q('#side-reference').textContent=scenes[index].side[2];q('#screen-status').textContent='Screen '+(index+1)+' of 6: '+scenes[index].nav;refreshScript();window.scrollTo(0,0)}\\nfunction notes(on=!notesOpen){notesOpen=on;q('#script-panel').hidden=!on;q('#notes').textContent=on?'Hide script':'Show script';q('#notes').setAttribute('aria-expanded',String(on))}\\nfunction seconds(){return Math.floor(elapsed+(started===null?0:(performance.now()-started)/1000))}\\nfunction tick(){const n=seconds();q('#clock').textContent=Math.floor(n/60)+':'+String(n%60).padStart(2,'0');q('#clock').className='timer'+(n>=180?' over':n>=170?' warn':'');q('#time-progress').style.width=Math.min(n/180*100,100)+'%';q('#timer-limit').textContent=n>=180?'3:00 LIMIT':'TARGET 2:50'}\\nfunction timer(){if(started===null){started=performance.now();q('#timer').textContent='Pause timer'}else{elapsed+=(performance.now()-started)/1000;started=null;q('#timer').textContent='Resume timer'}tick()}\\nfunction reset(){elapsed=0;started=null;q('#timer').textContent='Start rehearsal';notes(false);show(0);tick()}\\nnav.forEach(b=>b.onclick=()=>show(Number(b.dataset.scene)));q('#prev').onclick=()=>show(index-1);q('#next').onclick=()=>show(index+1);q('#notes').onclick=()=>notes();q('#close-script').onclick=()=>notes(false);q('#timer').onclick=timer;q('#reset').onclick=reset;\\nq('#full').hidden=!document.fullscreenEnabled;q('#full').onclick=async()=>{try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen()}catch(e){q('#screen-status').textContent='Full screen unavailable. Maximize the browser instead.'}};document.addEventListener('fullscreenchange',()=>q('#full').textContent=document.fullscreenElement?'Exit full screen':'Full screen');\\ndocument.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{q('#evidence-image').src=b.dataset.image;q('#evidence-image').alt=b.dataset.caption;q('#image-title').textContent=b.dataset.caption;q('#image-dialog').showModal()});q('#close-image').onclick=()=>q('#image-dialog').close();q('#sources').onclick=()=>q('#sources-dialog').showModal();q('#close-sources').onclick=()=>q('#sources-dialog').close();\\ndocument.addEventListener('keydown',e=>{if(e.ctrlKey||e.altKey||e.metaKey||document.querySelector('dialog[open]'))return;if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();show(index+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(index-1)}if(e.key.toLowerCase()==='n')notes();if(e.key.toLowerCase()==='t')timer();if(e.key==='Escape')notes(false)});setInterval(tick,250);show(0);tick();\\n\"")
base=json.loads((ROOT/'outputs/committee-run.json').read_text())
test=json.loads((ROOT/'outputs/cost15-run-record.json').read_text())
