assert base['base']['results']['Constrained']==b
NOTICE="AI-assisted educational presentation · Not financial or investment advice"
def pct(v): return f"{v*100:.3f}%"
def esc(s): return html.escape(s,quote=True)
colors={'QQQ':'#314c70','ONEQ':'#91abc4','VUG':'#bc8747','BIL':'#167c72','IEF':'#b7c7c1','LQD':'#d6c9b6'}
def allocation(weights,label):
    values=[(k,v) for k,v in weights.items() if v>0]
    parts=''.join(f'<span style="width:{v*100:.6f}%;background:{colors[k]};color:{"#18322c" if k=="ONEQ" else "white"}" title="{k} {v:.0%}">{v:.0%}</span>' for k,v in values)
    legend=''.join(f'<span><i style="background:{colors[k]}"></i>{k}</span>' for k,v in values)
    aria=esc(', '.join(f'{k} {v:.0%}' for k,v in weights.items()))
    return f'<div class="allocation"><div class="bar-label">{label}</div><div class="stack" role="img" aria-label="{aria}">{parts}</div><div class="legend">{legend}</div></div>'
def stat(label,value,sub):
    return f'<div class="stat"><span class="label">{label}</span><strong>{value}</strong><small>{sub}</small></div>'
rows=''
for name,r in base['base']['results'].items():
    reason='Risk > 10%' if name=='Equal weight' else ('Return < 7.49%' if name=='Inverse volatility' else 'All model rules')
